import { useSelector } from 'react-redux';
import type { RootState } from '../store';
import { Link } from 'react-router-dom';
import { useEffect, useState } from 'react';

const Header: React.FC = () => {
  const { isAuthenticated } = useSelector((state: RootState) => state.auth);
  const [theme, setTheme] = useState<'light' | 'dark' | 'romantic'>('light');

  // Initialize theme from localStorage or system preference
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark' | 'romantic' | null;
    if (savedTheme) {
      setTheme(savedTheme);
    } else {
      // Check system preference
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      setTheme(prefersDark ? 'dark' : 'light');
    }
  }, []);

  // Apply theme to document root
  useEffect(() => {
    // Remove all theme classes
    document.documentElement.classList.remove('dark', 'romantic');

    // Add the selected theme class (if not light)
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else if (theme === 'romantic') {
      document.documentElement.classList.add('romantic');
    }

    // Save to localStorage
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    const themes: ('light' | 'dark' | 'romantic')[] = ['light', 'dark', 'romantic'];
    const currentIndex = themes.indexOf(theme);
    const nextIndex = (currentIndex + 1) % themes.length;
    setTheme(themes[nextIndex]);
