    } else if (theme === 'romantic') {
      document.documentElement.classList.add('romantic');
    }

    // Save to localStorage
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    const themes: ('light' | 'dark' | 'romantic')[] = ['light', 'dark', 'romantic'];
    const currentIndex = themes.indexOf(theme);
    const nextIndex = (currentIndex + 1) % themes.length;
    setTheme(themes[nextIndex]);
  };

  return (
    <header className="bg-white/80 backdrop-blur-sm border-b border-[hsl(var(--border))]/50 sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex h-16 items-center justify-between">
          <div className="flex-shrink-0">
            <Link to="/" className="flex items-center space-x-3">
              <span className="h-8 w-8 flex items-center justify-center bg-primary/10 text-primary rounded-lg">
                C
              </span>
              <span className="text-xl font-bold text-foreground">
                Cue
              </span>
            </Link>
          </div>
          <div className="hidden md:flex md:items-center md:space-x-6">
            <Link to="/" className="text-gray-500 hover:text-gray-900 transition-colors">
              Home
            </Link>
            <Link to="/discovery" className="text-gray-500 hover:text-gray-900 transition-colors">
              Discover
            </Link>
            {!isAuthenticated ? (
              <>
                <Link to="/login" className="text-gray-500 hover:text-gray-900 transition-colors">
                  Login
                </Link>
                <Link to="/register" className="ml-4 text-gray-500 hover:text-gray-900 transition-colors">
                  Register
                </Link>
              </>
            ) : (
              <>
                <Link to="/profile" className="text-gray-500 hover:text-gray-900 transition-colors">
                  Profile
                </Link>
                <Link to="/provider" className="ml-4 text-gray-500 hover:text-gray-900 transition-colors">
                  Provider Hub
                </Link>
                <button
                  onClick={() => {
                    // In a real app, we would dispatch a logout action
                    // For now, we'll just remove the token and redirect
                    localStorage.removeItem('token');
                    window.location.reload();
                  }}
                  className="ml-4 text-gray-500 hover:text-gray-900 transition-colors"
                >
                  Logout
                </button>
              </>
            )}
          </div>
          <div className="flex items-center md:hidden space-x-2">
            {/* Mobile menu button */}
            <button
              className="p-2 rounded-md text-gray-500 hover:text-gray-900 hover-bg-gray-50"
              aria-label="Open main menu"
            >
              {/* Hamburger icon */}
              <svg className="h-6 w-6" stroke="currentColor" fill="none" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>

            {/* Theme toggle button */}
            <button
              onClick={toggleTheme}
              className="p-2 rounded-md text-gray-500 hover:text-gray-900 hover-bg-gray-50"
              title="Toggle theme"
              aria-label="Toggle theme"
            >
              {/* Theme icon based on current theme */}
              {theme === 'dark' ? (
                <svg className="h-5 w-5" stroke="currentColor" fill="none" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
                </svg>
              ) : theme === 'romantic' ? (
                <svg className="h-5 w-5" stroke="currentColor" fill="none" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
                </svg>
              ) : (
                <svg className="h-5 w-5" stroke="currentColor" fill="none" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
                </svg>
              )}
            </button>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;

