39	        var salt = RandomNumberGenerator.GetBytes(16);
40	        var hash = Rfc2898DeriveBytes.Pbkdf2(password, salt, 120_000, HashAlgorithmName.SHA256, 32);
41	        return $"v1:{Convert.ToBase64String(salt)}:{Convert.ToBase64String(hash)}";
42	    }
