45	    {
46	        var parts = encodedHash.Split(':');
47	        if (parts.Length != 3 || parts[0] != "v1") return false;
48	        var salt = Convert.FromBase64String(parts[1]);
49	        var expected = Convert.FromBase64String(parts[2]);
50	        var actual = Rfc2898DeriveBytes.Pbkdf2(password, salt, 120_000, HashAlgorithmName.SHA256, expected.Length);
51	        return CryptographicOperations.FixedTimeEquals(actual, expected);
52	    }
53	}
