60	        var credentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);
61	        var claims = new List<Claim> { new(JwtRegisteredClaimNames.Sub, user.Id.ToString()), new(JwtRegisteredClaimNames.Email, user.Email) };
62	        claims.AddRange(user.Roles.Select(role => new Claim(ClaimTypes.Role, role.ToString())));
63	        var expires = DateTime.UtcNow.AddMinutes(options.AccessTokenMinutes);
64	        var token = new JwtSecurityToken(options.Issuer, options.Audience, claims, expires: expires, signingCredentials: credentials);
65	        return new TokenResponse(new JwtSecurityTokenHandler().WriteToken(token), (int)(expires - DateTime.UtcNow).TotalSeconds);
