15	namespace AuthService.Controllers;
16	
17	[ApiController]
18	[Route("api/v1/auth")]
19	public sealed class AuthController(
20	    CueDbContext dbContext,
21	    PasswordService passwords,
22	    JwtTokenService tokens,
23	    IEmailSender emailSender,
24	    IOptions<AppOptions> appOptions) : ControllerBase
25	{
26	    private const string RefreshTokenCookie = "cue.refresh";
27	
28	    [HttpPost("register")]
29	    public async Task<ActionResult<TokenResponse>> Register(RegisterRequest request, CancellationToken cancellationToken)
30	    {
31	        // The unique index spans deleted accounts too, so any existing row blocks
32	        // reuse until anonymization/purge lands.
33	        if (await dbContext.Users.AnyAsync(user => user.Email == request.Email.Trim().ToLower(), cancellationToken))
34	        {
35	            return Conflict(new { error = "An account with this email already exists." });
36	        }
37	
38	        if (!Enum.TryParse<UserRole>(request.Role, true, out var role))
39	        {
40	            return BadRequest(new { error = "Role must be Seeker, Provider, or Admin." });
41	        }
42	
43	        var user = new User(request.Email, request.FirstName, request.LastName, role);
44	        user.SetPasswordHash(passwords.Hash(request.Password));
45	        dbContext.Users.Add(user);
46	
47	        var tokenResponse = await IssueTokensAsync(user, cancellationToken);
48	        await dbContext.SaveChangesAsync(cancellationToken);
49	
50	        // Fire after save so the user row exists; verification never blocks registration.
51	        try
52	        {
53	            await SendVerificationEmailAsync(user, cancellationToken);
54	        }
55	        catch (Exception ex)
56	        {
57	            Console.WriteLine($"Verification email failed for {user.Email}: {ex.Message}");
58	        }
59	
60	        return StatusCode(StatusCodes.Status201Created, tokenResponse);
61	    }
62	
63	    [HttpPost("login")]
64	    public async Task<ActionResult<TokenResponse>> Login(LoginRequest request, CancellationToken cancellationToken)
65	    {
66	        var user = await dbContext.Users.SingleOrDefaultAsync(candidate => candidate.Email == request.Email.Trim().ToLower(), cancellationToken);
67	        if (user?.PasswordHash is null || user.IsDeleted || !passwords.Verify(request.Password, user.PasswordHash))
68	        {
69	            return Unauthorized(new { error = "Invalid email or password." });
70	        }
71	
